**Modular Distributed Key-Value Store Design**
=============================================

### Overview

The proposed design consists of three decoupled layers:

1.  **Consistent Hashing Ring Router**: responsible for distributing keys across virtual nodes.
2.  **Storage Engine**: maintains LSM-Tree memtables and SSTable disk flushes for efficient data storage and retrieval.
3.  **Anti-Entropy Repair Subsystem**: utilizes Merkle trees to synchronize divergent replicas and ensure data consistency across the distributed system.

### Layer 1: Consistent Hashing Ring Router

#### Consistent Hashing Implementation

```python
import hashlib
import bisect

class ConsistentHashingRing:
    def __init__(self, nodes=None, replicas=100):
        self.ring = dict()
        self.sorted_keys = []
        self.replicas = replicas

        if nodes:
            for node in nodes:
                self.add_node(node)

    def add_node(self, node):
        for i in range(self.replicas):
            key = f"{node}:{i}"
            hash_key = self._hash(key)
            if hash_key not in self.ring:
                self.ring[hash_key] = node
                bisect.insort(self.sorted_keys, hash_key)

    def remove_node(self, node):
        for i in range(self.replicas):
            key = f"{node}:{i}"
            hash_key = self._hash(key)
            if hash_key in self.ring:
                del self.ring[hash_key]
                self.sorted_keys.remove(hash_key)

    def get_node(self, string_key):
        if not self.ring:
            return None
        hash_key = self._hash(string_key)
        index = bisect.bisect(self.sorted_keys, hash_key)
        if index == len(self.sorted_keys):
            return self.ring[self.sorted_keys[0]]
        return self.ring[self.sorted_keys[index]]

    def _hash(self, key):
        return int(hashlib.md5(key.encode()).hexdigest(), 16)

# Example usage
nodes = ["node1", "node2", "node3"]
ring = ConsistentHashingRing(nodes)

key = "example_key"
node = ring.get_node(key)
print(f"Key {key} is stored on node {node}")
```

### Layer 2: Storage Engine

#### LSM-Tree Implementation

```python
import os
import pickle

class SSTable:
    def __init__(self, filename):
        self.filename = filename
        self.data = {}

    def put(self, key, value):
        self.data[key] = value

    def get(self, key):
        return self.data.get(key)

    def flush(self):
        with open(self.filename, "wb") as f:
            pickle.dump(self.data, f)

    @classmethod
    def load(cls, filename):
        if not os.path.exists(filename):
            return cls(filename)
        with open(filename, "rb") as f:
            data = pickle.load(f)
        sstable = cls(filename)
        sstable.data = data
        return sstable

class MemTable:
    def __init__(self):
        self.data = {}

    def put(self, key, value):
        self.data[key] = value

    def get(self, key):
        return self.data.get(key)

    def flush(self, sstable_filename):
        sstable = SSTable(sstable_filename)
        for key, value in self.data.items():
            sstable.put(key, value)
        sstable.flush()
        self.data.clear()

class LSMTree:
    def __init__(self, sstable_filename):
        self.memtable = MemTable()
        self.sstable_filename = sstable_filename

    def put(self, key, value):
        self.memtable.put(key, value)

    def get(self, key):
        value = self.memtable.get(key)
        if value is None:
            sstable = SSTable.load(self.sstable_filename)
            value = sstable.get(key)
        return value

    def flush_memtable(self):
        self.memtable.flush(self.sstable_filename)

# Example usage
lsmtree = LSMTree("example.sstable")

key = "example_key"
value = "example_value"
lsmtree.put(key, value)

print(lsmtree.get(key))  # Output: example_value
```

### Layer 3: Anti-Entropy Repair Subsystem

#### Merkle Tree Implementation

```python
import hashlib

class MerkleTree:
    def __init__(self, leaves):
        self.leaves = leaves
        self.tree = self.build_tree(leaves)

    def build_tree(self, leaves):
        if len(leaves) == 1:
            return leaves[0]
        if len(leaves) % 2 == 1:
            leaves.append(self.hash(leaves[-1]))
        tree = []
        for i in range(0, len(leaves), 2):
            left = leaves[i]
            right = leaves[i + 1]
            tree.append(self.hash(left + right))
        return self.build_tree(tree)

    def hash(self, value):
        return hashlib.sha256(value.encode()).hexdigest()

    def get_root(self):
        return self.tree

# Example usage
leaves = ["leaf1", "leaf2", "leaf3"]
merkletree = MerkleTree(leaves)

root = merkletree.get_root()
print(root)
```

### Integration

To integrate the three layers, you can use the following example:

```python
# Create a Consistent Hashing Ring Router
nodes = ["node1", "node2", "node3"]
ring = ConsistentHashingRing(nodes)

# Create an LSM-Tree Storage Engine for each node
storage_engines = {}
for node in nodes:
    storage_engines[node] = LSMTree(f"{node}.sstable")

# Create an Anti-Entropy Repair Subsystem
def repair_subsystem(node1, node2):
    # Get the Merkle tree roots for each node
    root1 = MerkleTree([f"{node1}.sstable"]).get_root()
    root2 = MerkleTree([f"{node2}.sstable"]).get_root()

    # Compare the Merkle tree roots
    if root1 != root2:
        # Sync the data between the nodes
        print(f"Syncing data between {node1} and {node2}")

# Example usage
key = "example_key"
node = ring.get_node(key)

# Store the key-value pair in the corresponding node's storage engine
storage_engines[node].put(key, "example_value")

# Run the anti-entropy repair subsystem
repair_subsystem("node1", "node2")
```

This design provides a modular and scalable Distributed Key-Value Store with three decoupled layers for data distribution, storage, and consistency.
